new = pd.read_csv("learning/data/instances.csv"); old = pd.read_csv("/tmp/instances_36.csv")
for c in old.columns:
    if new[c].dtype==object:
        if not (new[c]==old[c]).all(): print("differs:", c)
    else:
        d = (new[c].fillna(-9).values != old[c].fillna(-9).values)
